import{COST,applyAuto,round,sma,rsi,correlation,returns,indicators,execution,trade,value,metrics,backtest,validateDataset,validateState}from'./engine.js';
const $=s=>document.querySelector(s),KEY='dalal-street-lab-v1',fmt=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(n),pc=n=>(n>=0?'+':'')+n.toFixed(2)+'%',num=n=>new Intl.NumberFormat('en-IN',{maximumFractionDigits:2}).format(n),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),date=s=>new Date(s+'T00:00:00Z').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}),colors=['#245f49','#b69a5a','#7c958b','#b5c194','#987a63','#91a5b5'];
let data,state,page='market',symbol='RELIANCE.BO',range=60,side='buy',query='',busy=false,labResults=null,stale=false;
function portfolio(name,strategy='Custom',initial=100000){return{id:crypto.randomUUID(),name,strategy,initial,cash:initial,realized:0,holdings:{},trades:[],history:[],auto:null}}
function fresh(d){let portfolios=[portfolio('The long game','Buy & hold'),portfolio('Momentum desk','Trend following'),portfolio('Contrarian corner','Mean reversion')];let cursor=Math.min(120,d.stocks[0].bars.length-2);for(let p of portfolios)p.history=[{index:cursor,value:p.initial}];return{version:1,datasetId:d.id,cursor,portfolios,active:portfolios[0].id,completed:[]}}
function save(){try{localStorage.setItem(KEY,JSON.stringify({data,state}))}catch{toast('Browser storage is full or unavailable. Export a backup to keep your work.')}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
const active=()=>state.portfolios.find(p=>p.id===state.active),stock=()=>data.stocks.find(s=>s.symbol===symbol),bars=s=>s.bars.slice(0,state.cursor+1),last=s=>s.bars[state.cursor],change=s=>(last(s).c/s.bars[state.cursor-1].c-1)*100;
function dialog(content){$('#modalContent').innerHTML='<button class="close" aria-label="Close dialog">×</button>'+content;$('#modal .close').onclick=()=>$('#modal').close();$('#modal').showModal()}
function snapshot(p){let val=value(p,data.stocks,state.cursor),h={index:state.cursor,value:val};if(p.history.at(-1)?.index===state.cursor)p.history[p.history.length-1]=h;else p.history.push(h)}
function linePath(values,w=600,h=180,pad=15){let min=Math.min(...values),max=Math.max(...values),span=max-min||1;return values.map((v,i)=>(i?'L':'M')+(pad+i*(w-2*pad)/Math.max(1,values.length-1)).toFixed(1)+','+(h-pad-(v-min)/span*(h-2*pad)).toFixed(1)).join(' ')}
function spark(s){let a=bars(s).slice(-24).map(b=>b.c);return`<svg class="spark" viewBox="0 0 72 24" aria-hidden="true"><path d="${linePath(a,72,24,2)}" fill="none" stroke="${a.at(-1)>=a[0]?'#367357':'#b86656'}" stroke-width="1.4"/></svg>`}
function chart(s){let all=bars(s),a=all.slice(-range),offset=all.length-a.length,s20=sma(all.map(x=>x.c),20).slice(offset),s50=sma(all.map(x=>x.c),50).slice(offset),W=720,H=255,left=12,right=66,top=20,bottom=32,high=Math.max(...a.map(x=>x.h),...s50.filter(x=>x!==null)),low=Math.min(...a.map(x=>x.l),...s50.filter(x=>x!==null)),span=high-low||1;high+=span*.1;low-=span*.1;span=high-low;let X=i=>left+(i+.5)*(W-left-right)/a.length,Y=v=>top+(high-v)/span*(H-top-bottom),cw=Math.max(1,Math.min(7,(W-left-right)/a.length*.65));let lines=Array.from({length:5},(_,i)=>{let v=low+span*i/4,y=Y(v);return`<line x1="${left}" y1="${y}" x2="${W-right}" y2="${y}" stroke="#e9ece2" stroke-dasharray="3 5"/><text x="${W-right+10}" y="${y+3}">${num(v)}</text>`}).join('');let candles=a.map((b,i)=>{let col=b.c>=b.o?'#50785a':'#bb8069';return`<g><title>${esc(b.date)} | O ${b.o} H ${b.h} L ${b.l} C ${b.c} | volume ${b.v}</title><line x1="${X(i)}" x2="${X(i)}" y1="${Y(b.h)}" y2="${Y(b.l)}" stroke="${col}"/><rect x="${X(i)-cw/2}" y="${Math.min(Y(b.o),Y(b.c))}" width="${cw}" height="${Math.max(1,Math.abs(Y(b.o)-Y(b.c)))}" fill="${col}"/></g>`}).join('');let path=(a,color)=>`<path d="${a.map((v,i)=>v===null?'':(i===0||a[i-1]===null?'M':'L')+X(i).toFixed(1)+','+Y(v).toFixed(1)).join(' ')}" fill="none" stroke="${color}" stroke-width="1.6"/>`;let labels=[0,Math.floor(a.length/2),a.length-1].map(i=>`<text x="${X(i)}" y="${H-10}" text-anchor="middle">${date(a[i].date).replace(/ \d{4}/,'')}</text>`).join('');return`<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(s.name)} daily candlestick chart with 20 and 50 session moving averages">${lines}${candles}${path(s20,'#b59a56')}${path(s50,'#8fa7ae')}${labels}</svg>`}
function equityChart(series){let all=series.flatMap(x=>x.values),W=740,H=225,pad=35,min=Math.min(0,...all),max=Math.max(1,...all),span=max-min||1,X=(i,n)=>pad+i*(W-2*pad)/Math.max(1,n-1),Y=v=>H-pad-(v-min)/span*(H-2*pad);return`<div class="legend">${series.map((s,i)=>`<b style="font-weight:400"><i class="color-dot" style="background:${colors[i%colors.length]}"></i>${esc(s.name)}</b>`).join('')}</div><svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Normalized percentage returns comparison">${Array.from({length:4},(_,i)=>{let v=min+span*i/3,y=Y(v);return`<line x1="${pad}" x2="${W-pad}" y1="${y}" y2="${y}" stroke="#e3e8db"/><text x="2" y="${y+3}">${v.toFixed(1)}%</text>`}).join('')}${series.map((s,j)=>`<path d="${s.values.map((v,i)=>(i?'L':'M')+X(i,s.values.length)+','+Y(v)).join(' ')}" fill="none" stroke="${colors[j%colors.length]}" stroke-width="2"/>`).join('')}</svg>`}
function stats(){let p=active(),total=value(p,data.stocks,state.cursor),cost=Object.values(p.holdings).reduce((s,h)=>s+h.cost,0),invested=total-p.cash,ret=(total/p.initial-1)*100;return`<div class="cards"><div class="stat featured"><span class="label">Portfolio value ↗</span><strong>${fmt(total)}</strong><small><span class="${ret>=0?'up':'down'}">${pc(ret)}</span> since inception</small></div><div class="stat"><span class="label">Available to invest</span><strong>${fmt(p.cash)}</strong><small>${(p.cash/total*100).toFixed(1)}% in cash · ${esc(p.name)}</small></div><div class="stat"><span class="label">Unrealized P&L</span><strong class="${invested-cost>=0?'up':'down'}">${fmt(invested-cost)}</strong><small>Realized: ${fmt(p.realized)}</small></div><div class="stat"><span class="label">Positions held</span><strong>${Object.keys(p.holdings).length.toString().padStart(2,'0')} <span style="font:12px var(--sans);color:var(--muted)">/ ${data.stocks.length} stocks</span></strong><small>₹1,00,000 starter portfolios · long-only</small></div></div>`}
function render(){if(!data)return;let title={market:["YOUR SEAT AT THE EXCHANGE","Great investors start<br>with a little practice.","Build conviction. Test your ideas. Keep the money imaginary.","TRADING FLOOR"],portfolios:["ONE INVESTOR. MANY POSSIBILITIES.","Your ideas, in portfolios.","Give each investing philosophy a place to prove itself.","MY PORTFOLIOS"],lab:["TURN A HUNCH INTO AN EXPERIMENT","Less guesswork.<br>More evidence.","Compare rule-based strategies on the same historical window.","STRATEGY LAB"],learn:["INVEST IN YOUR UNDERSTANDING","Learn the language<br>of the long game.","Six short lessons. A lifetime of better questions.","INVESTOR ACADEMY"],settings:["KNOW WHAT YOU ARE LOOKING AT","A transparent<br>practice floor.","Your data, your assumptions, your portfolios.","DATA & SETTINGS"]}[page];$('#eyebrow').textContent=title[0];$('#heading').innerHTML=title[1];$('#subtitle').textContent=title[2];$('#pageLabel').textContent=title[3];$('#replayDate').textContent=date(last(stock()).date);$('#dataDescription').textContent=data.mode==='demo'?'Synthetic prices · illustrative sessions':'BSE historical · 30+ day lag';$('#dataBadge').textContent=data.mode==='demo'?'ILLUSTRATIVE DATA':'BSE HISTORICAL REPLAY';$('#dataBadge').className='badge '+(data.mode==='demo'?'amber':'');$('#replayLabel').textContent=data.mode==='demo'?'Demo session · not actual BSE quotes':'API historical replay · adjusted prices';$('#replayProgress').textContent=` · ${state.cursor+1} / ${stock().bars.length}`;$('#nextDay').disabled=$('#nextWeek').disabled=busy||state.cursor>=stock().bars.length-1;$('#ticker').innerHTML=`<div class="scroll-ticker" style="display:flex;gap:32px">${[...data.stocks,...data.stocks].map(s=>`<span><b>${esc(s.symbol.replace('.BO',''))}</b> ${num(last(s).c)} <b style="color:${change(s)>=0?'#b7d799':'#d7957e'}">${change(s)>=0?'↗':'↘'} ${pc(change(s))}</b></span>`).join('')}</div>`;$('#nav').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#view').innerHTML=({market:marketView,portfolios:portfolioView,lab:labView,learn:learnView,settings:settingsView}[page])();bind()}
function marketView(){let s=stock(),p=active(),ind=indicators(bars(s)),ch=change(s),m=ind.macd;return stats()+`<div class="grid-floor"><div><section class="panel"><div class="panel-head"><h2>The market, in focus</h2><div class="tabs">${[30,60,120].map(n=>`<button data-range="${n}" class="${range===n?'active':''}">${n}D</button>`).join('')}</div></div><div class="stock-header"><div class="stock-title"><span class="stock-icon">${esc(s.name[0])}</span><div><strong>${esc(s.name)}</strong><small>BSE ${esc(s.code||'')} · ${esc(s.symbol)} · ${esc(s.sector)}</small></div></div><div class="stock-price">${fmt(last(s).c)}<small class="${ch>=0?'up':'down'}">${pc(ch)} this session</small></div></div><div class="legend"><span>Daily candles</span><span>SMA 20</span><span>SMA 50</span></div><div class="chart-wrap">${chart(s)}</div><div class="chart-caption"><span>${data.mode==='demo'?'SYNTHETIC OHLCV':'ADJUSTED OHLCV'} · NO FUTURE DATA</span><span>Volume: ${num(last(s).v)}</span></div><div class="indicator-grid"><div class="indicator"><small>RSI (14) · MOMENTUM</small><strong>${ind.rsi?.toFixed(1)??'—'} <span class="pill">${ind.rsi<30?'Oversold':ind.rsi>70?'Overbought':'Neutral'}</span></strong><p>Extreme readings can persist. They are observations, not orders.</p></div><div class="indicator"><small>MOVING AVERAGES</small><strong>${ind.s20>ind.s50?'20 above 50':'20 below 50'}</strong><p>${ind.cross}. Lagging measures of trend.</p></div><div class="indicator"><small>MACD (12, 26, 9)</small><strong class="${m?.histogram>=0?'up':'down'}">${m?num(m.histogram):'—'}</strong><p>Histogram: MACD minus signal. Can whipsaw in sideways markets.</p></div></div></section><section class="panel"><div class="panel-head"><h2>Your watchlist <small style="font:9px var(--mono);color:var(--muted)"> / BSE</small></h2><input id="search" class="search" aria-label="Search stocks" placeholder="Search company or sector" value="${esc(query)}"></div><div class="table-wrap"><table><thead><tr><th>COMPANY</th><th class="num">PRICE / ₹</th><th class="num">CHANGE</th><th>TREND</th><th>SECTOR</th></tr></thead><tbody id="watchRows">${watchRows()}</tbody></table></div></section></div><div><section class="panel trade-panel"><div class="panel-head"><h2>Make your move</h2><span class="pill">PAPER TRADE</span></div><div class="panel-body"><label class="form-label" for="tradePortfolio" style="margin-top:0">Portfolio</label><select id="tradePortfolio">${state.portfolios.map(x=>`<option value="${esc(x.id)}" ${x.id===p.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><div class="side-choice"><button data-side="buy" class="${side==='buy'?'active':''}">BUY</button><button data-side="sell" class="${side==='sell'?'active':''}">SELL</button></div><label class="form-label" for="tradeSymbol">Stock</label><select id="tradeSymbol">${data.stocks.map(x=>`<option value="${esc(x.symbol)}" ${x.symbol===s.symbol?'selected':''}>${esc(x.symbol)}</option>`).join('')}</select><label class="form-label" for="quantity">Shares <span id="owned" style="float:right">OWN ${p.holdings[s.symbol]?.qty||0}</span></label><div style="display:flex;gap:7px"><input id="quantity" type="number" min="1" max="10000000" step="1" value="1" inputmode="numeric"><button class="btn" id="maxQty">Max</button></div><label class="form-label" for="tradeNote">Your thesis <span class="muted">(optional)</span></label><textarea id="tradeNote" rows="2" maxlength="300" placeholder="What is your reason for this trade?"></textarea><div class="trade-summary" id="tradeSummary"></div><button id="reviewOrder" class="btn green wide">Review ${side} order →</button><p class="fine">Close-price simulation · 0.05% slippage + 0.10% fee per side. Adjusted-price units; no real orders.</p></div></section><section class="panel"><div class="insight"><span class="eyebrow">THE INVESTOR'S NOTEBOOK</span><h3>Don't collect stocks.<br>Build a portfolio.</h3><p>Owning two technology stocks may double down on the same risk. Compare sectors and the correlation of daily returns to explore complementary exposure.</p><button class="text-link" data-go="portfolios">Explore diversification ↗</button></div></section><section class="panel"><div class="insight"><span class="eyebrow">PATTERN WATCH / ${esc(s.symbol)}</span>${patternText(s)}<button class="text-link" data-go="lab">Test a rule in the lab ↗</button></div></section></div></div>`}
function watchRows(){let found=data.stocks.filter(s=>(s.name+s.symbol+s.sector+s.code).toLowerCase().includes(query.toLowerCase()));return found.length?found.map(s=>`<tr class="stock-row ${s.symbol===symbol?'selected':''}" data-stock="${esc(s.symbol)}"><td><button class="symbol-button" data-stock="${esc(s.symbol)}">${esc(s.symbol.replace('.BO',''))}</button><span class="company">${esc(s.name)}</span></td><td class="num">${num(last(s).c)}</td><td class="num ${change(s)>=0?'up':'down'}">${pc(change(s))}</td><td>${spark(s)}</td><td><span class="pill neutral">${esc(s.sector)}</span></td></tr>`).join(''):'<tr><td colspan="5" class="empty">No matching stocks. Try a sector or company name.</td></tr>'}
function patternText(s){let a=bars(s),p=last(s).c,prev=a.slice(-21,-1),hi=Math.max(...prev.map(x=>x.h)),lo=Math.min(...prev.map(x=>x.l)),avg=prev.reduce((t,b)=>t+b.v,0)/20,i=indicators(a),breakout=p>hi,breakdown=p<lo;return`<h3>${breakout?'20-session breakout':breakdown?'20-session breakdown':'Inside the recent range'}</h3><p>Close ${fmt(p)} versus prior 20-session high ${fmt(hi)} and low ${fmt(lo)}. Volume is ${(last(s).v/avg).toFixed(2)}× the prior average.</p><p>${i.cross}. This simple rule detects a price condition; it cannot predict the next move.</p>`}
function portfolioView(){let p=active(),total=value(p,data.stocks,state.cursor),hold=Object.entries(p.holdings),sectors={};for(let[sym,h]of hold){let s=data.stocks.find(x=>x.symbol===sym);sectors[s.sector]=(sectors[s.sector]||0)+h.qty*last(s).c}let largest=Object.values(sectors).length?Math.max(...Object.values(sectors))/total*100:0;let commonStart=Math.max(...state.portfolios.map(p=>p.history[0].index));let aligned=state.portfolios.filter(p=>p.history.length>0).map(p=>{let map=new Map(p.history.map(h=>[h.index,h.value]));let start=map.get(commonStart)||p.initial;return{name:p.name,values:Array.from({length:state.cursor-commonStart+1},(_,j)=>((map.get(j+commonStart)??start)/start-1)*100)}});return`<div class="section-title"><h2>Different ideas. Same starting line.</h2><button class="btn dark" id="newPortfolio">+ New portfolio</button></div><div class="portfolio-list">${state.portfolios.map((x,j)=>{let v=value(x,data.stocks,state.cursor),ret=(v/x.initial-1)*100;return`<div class="portfolio-card ${x.id===p.id?'active':''}"><span class="eyebrow">${esc(x.strategy)}</span><h3>${esc(x.name)}</h3><div class="value">${fmt(v)}</div><span class="${ret>=0?'up':'down'} mono" style="font-size:11px">${pc(ret)} since inception</span><div class="allocation">${Object.entries(x.holdings).map(([sym,h],i)=>`<span title="${esc(sym)}" style="width:${h.qty*last(data.stocks.find(s=>s.symbol===sym)).c/v*100}%;background:${colors[i%colors.length]}"></span>`).join('')}</div><div class="flex fine"><span>${Object.keys(x.holdings).length} positions</span><span>${x.trades.length} trades · ${fmt(x.cash)} cash</span></div><button class="btn ${x.id===p.id?'dark':''}" data-select-portfolio="${esc(x.id)}">${x.id===p.id?'Active portfolio':'Use this portfolio →'}</button><button class="btn subtle" data-auto-portfolio="${esc(x.id)}">${x.auto?'⚡ Auto rule ON':'Set auto rule ⚡'}</button>${x.auto?`<p class="fine">${esc(x.auto.rule)} · ${esc(x.auto.symbol)} · ${(x.auto.allocation*100).toFixed(0)}% entry size</p>`:''}</div>`}).join('')}</div><div class="section-title"><h2>Compare your conviction</h2><span class="fine">Common period · fees included</span></div><section class="panel"><div class="panel-head"><h2>Portfolio returns</h2><span class="pill">NORMALIZED AT ${date(stock().bars[commonStart].date)}</span></div><div class="panel-body">${equityChart(aligned)}<p class="fine">Values are marked at replay closes. Return lines start together at the latest portfolio's creation date; cash counts toward equity. Inception returns above may cover different periods.</p></div></section><section class="panel"><div class="panel-head"><h2>${esc(p.name)} / holdings</h2><button class="text-link" data-go="market">Make a trade ↗</button></div><div class="table-wrap">${hold.length?`<table><thead><tr><th>STOCK</th><th class="num">SHARES</th><th class="num">AVG COST*</th><th class="num">VALUE</th><th class="num">UNREALIZED P&L</th><th class="num">WEIGHT</th></tr></thead><tbody>${hold.map(([sym,h])=>{let s=data.stocks.find(s=>s.symbol===sym),v=last(s).c*h.qty,pnl=v-h.cost;return`<tr><td><button class="symbol-button" data-open-stock="${esc(sym)}">${esc(sym)}</button><span class="company">${esc(s.sector)}</span></td><td class="num">${h.qty}</td><td class="num">${fmt(h.cost/h.qty)}</td><td class="num">${fmt(v)}</td><td class="num ${pnl>=0?'up':'down'}">${fmt(pnl)}</td><td class="num">${(v/total*100).toFixed(1)}%</td></tr>`}).join('')}</tbody></table><p class="fine" style="padding:0 18px 12px">*Weighted average entry cost includes simulated fees.</p>`:'<div class="empty">Your first investment starts with a hypothesis.<br>Pick a stock on the trading floor and record why you chose it.</div>'}</div></section><section class="panel"><div class="panel-head"><h2>The diversification desk</h2><span class="pill neutral">60-SESSION RETURN CORRELATION</span></div><div class="panel-body"><div class="flex"><span class="fine">Largest sector: ${largest.toFixed(1)}% of total equity · cash ${(p.cash/total*100).toFixed(1)}%</span><select id="pairBase" style="width:200px">${data.stocks.map(s=>`<option value="${esc(s.symbol)}" ${s.symbol===symbol?'selected':''}>${esc(s.symbol)}</option>`).join('')}</select></div><p class="fine">Explore stocks in different sectors with lower historical co-movement to ${esc(symbol)}. Lower correlation does not guarantee protection, and two stocks are not a complete diversified portfolio.</p><div class="pair-grid" style="margin-top:18px">${complements()}</div><div class="callout">Correlation uses daily percentage returns on the same 60 sessions, not price levels. Sector labels describe business exposure; correlation can rise during a crisis. Include position sizing, time horizon and fundamental research in your decisions.</div></div></section><section class="panel"><div class="panel-head"><h2>Your trade journal</h2><span class="fine">${p.trades.length} decisions recorded</span></div><div class="table-wrap">${p.trades.length?`<table><thead><tr><th>SESSION / ORDER</th><th>STOCK</th><th class="num">SHARES / FILL</th><th class="num">FEE</th><th>THESIS</th></tr></thead><tbody>${p.trades.slice().reverse().slice(0,100).map(t=>`<tr><td>${date(t.date)}<span class="company ${t.side==='buy'?'up':'down'}">${t.side.toUpperCase()} · ${t.executionBasis==='open'?'NEXT OPEN':'CLOSE'}</span></td><td>${esc(t.symbol)}</td><td class="num">${t.qty} × ${fmt(t.fill)}</td><td class="num">${fmt(t.fee)}</td><td style="max-width:260px;overflow-wrap:anywhere">${esc(t.note||'No thesis recorded')}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Every trade tells a story. Yours will appear here.</div>'}</div></section>`}
function complements(){let base=stock(),a=returns(bars(base).slice(-61).map(b=>b.c));let candidates=data.stocks.filter(s=>s.symbol!==symbol&&s.sector!==base.sector).map(s=>({s,c:correlation(a,returns(bars(s).slice(-61).map(b=>b.c)))})).filter(x=>x.c!==null).sort((a,b)=>a.c-b.c).slice(0,3);return candidates.map(({s,c})=>`<div class="pair-card"><span class="eyebrow">${esc(s.sector)}</span><p><strong>${esc(s.symbol)}</strong></p><span class="correlation">${c.toFixed(2)}</span><span class="fine"> / correlation</span><p>${c<0?'Historically moved in opposite directions on average.':c<.4?'Relatively low co-movement in this window.':'Positive co-movement; some shared market exposure.'}</p><button class="text-link" data-open-stock="${esc(s.symbol)}">Inspect the evidence ↗</button></div>`).join('')}
function labView(){let results=labResults;return`<section class="panel"><div class="panel-head"><h2>The experiment bench</h2><span class="pill">NO LOOK-AHEAD</span></div><div class="panel-body"><div class="lab-controls"><div><label class="form-label" for="labStock" style="margin-top:0">Test a stock</label><select id="labStock">${data.stocks.map(s=>`<option value="${esc(s.symbol)}" ${s.symbol===(results?.symbol||symbol)?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div><label class="form-label" for="labWindow" style="margin-top:0">History through replay date</label><select id="labWindow"><option value="120">Last 120 sessions</option><option value="260" ${results?.window===260?'selected':''}>Last 260 sessions</option></select></div><button id="runLab" class="btn dark">Run all 3 strategies ↗</button></div><div class="callout">₹1,00,000 each. Long-only, whole shares. Signals are computed at the close and filled at the following session's open. A 50-session warm-up is shared by every strategy. Costs: 0.10% fee + 0.05% slippage per side. No leverage. Open positions are marked at the last close.</div><div class="strategy-grid">${[['01','Buy & hold','Buy once after the shared warm-up and stay invested. A baseline against which active rules should earn their keep.'],['02','Trend following','Hold while the 20-session SMA is above the 50-session SMA. Exit when the relationship reverses. May lose to repeated whipsaws.'],['03','Mean reversion','Buy when RSI (14) is below 30. Exit when it is above 70. A falling price can remain oversold for a long time.']].map(([n,t,p])=>`<div class="strategy-card"><span class="eyebrow">RULE ${n}</span><h3 style="margin-top:10px">${t}</h3><p>${p}</p></div>`).join('')}</div></div></section>${results?`<section class="panel"><div class="panel-head"><h2>Results / ${esc(results.symbol)}</h2><span class="fine">${date(results.start)} → ${date(results.end)}</span></div><div class="panel-body">${equityChart(results.items.map(x=>({name:x.name,values:x.curve.map(v=>(v/100000-1)*100)})))}<div class="table-wrap"><table><thead><tr><th>STRATEGY</th><th class="num">FINAL EQUITY</th><th class="num">TOTAL RETURN</th><th class="num">MAX DRAWDOWN</th><th class="num">FILLS</th></tr></thead><tbody>${results.items.map(x=>`<tr><td>${x.name}</td><td class="num">${fmt(x.final)}</td><td class="num ${x.ret>=0?'up':'down'}">${pc(x.ret)}</td><td class="num down">−${x.drawdown.toFixed(2)}%</td><td class="num">${x.trades}</td></tr>`).join('')}</tbody></table></div><p class="fine">${data.mode==='demo'?'These results use synthetic prices and say nothing about actual BSE performance.':'These results use adjusted historical OHLCV. Corporate actions are reflected in the adjusted prices, not separate cash dividends.'} Zero fills is a valid outcome: the rule may never trigger. Changing the stock or period changes the result.</p></div></section>`:'<section class="panel"><div class="empty" style="padding:50px"><span style="font:42px var(--serif);color:#a8b791">⌁</span><h2 style="margin:12px">Let your idea meet the data.</h2><p>Select a stock and run the experiment to reveal the comparison.</p></div></section>'}<section class="panel"><div class="insight"><span class="eyebrow">HOW TO READ THE RESULTS</span><h3>The highest return isn't the whole story.</h3><p>Drawdown measures the biggest peak-to-trough decline in equity. Ask how much loss you could tolerate, how often a strategy trades, and whether it survives a different market period. Test an idea on unseen data before trusting a historical result. These simple rules are learning exercises, not buy/sell recommendations.</p><button class="text-link" data-go="learn">Learn about risk and overfitting ↗</button></div></section>`}
const lessons=[{title:'You own a business.',tag:'THE FOUNDATION',text:'A share is a small ownership stake in a company. Its price is what someone will pay today; its value depends on the cash the business can generate over time. Before buying, describe how the company makes money, who buys its products, and what could go wrong. Price movements alone do not answer those questions.',q:'What does owning one share represent?',opts:['A small ownership stake in a company','A guaranteed interest payment','A promise the price will rise'],answer:0,why:'Equity gives ownership, not a guaranteed return. Start with the business, then study its valuation.'},{title:'Price is not value.',tag:'FUNDAMENTAL THINKING',text:'Revenue is sales. Profit is what remains after expenses. Free cash flow is cash available after operating needs and investment. The price-to-earnings ratio compares share price with earnings per share, but a low ratio can reflect real business trouble. Compare competitors, debt, margins, governance and growth assumptions. This app does not fabricate fundamental data: inspect published annual reports before forming a thesis.',q:'Is a low P/E ratio enough to decide a stock is cheap?',opts:['Yes, always','No; earnings quality and prospects also matter','Only if its price fell yesterday'],answer:1,why:'A low multiple can signal weak growth, cyclical peak earnings, or financial distress. Valuation requires context.'},{title:'Different stocks. Different risks.',tag:'PORTFOLIO CONSTRUCTION',text:'Two banks can share interest-rate and credit-cycle risk. A bank and a consumer business may have different drivers, yet both can fall in a market sell-off. Diversification spreads exposure; it does not eliminate risk. Correlation ranges from −1 to +1 and describes past co-movement, not a permanent relationship. Use return correlations, sector exposure and position weights together. Cash is part of your allocation too.',q:'What is the strongest diversification question?',opts:['Do the ticker names look different?','Did both rise today?','Are the underlying business risks and exposures different?'],answer:2,why:'Complementarity comes from different sources of risk. A low historical correlation is only one piece of evidence.'},{title:'Indicators describe. They don’t promise.',tag:'TECHNICAL ANALYSIS',text:'A moving average smooths closing prices and lags the market. RSI measures recent gains relative to losses; readings below 30 or above 70 are commonly called oversold or overbought. MACD compares two exponential averages and a signal line. Breakouts identify moves beyond a prior range. All can fail. Write an explicit entry and exit rule, then test it with costs and without using future data.',q:'RSI is below 30. What does that tell you?',opts:['A rebound is certain','Recent losses dominate; further falls are possible','The company has no debt'],answer:1,why:'An oversold reading describes momentum. It does not guarantee a bottom, and it says nothing about company debt.'},{title:'Plan the loss before the gain.',tag:'RISK & POSITION SIZING',text:'Your time horizon and ability to absorb losses should shape your allocation. Position sizing sets how much of your portfolio depends on one company. A stop-loss is a rule to exit below a threshold, not a guarantee of that execution price; gaps can skip it. Drawdown is the decline from a prior equity peak. In this simulator there are no live stop orders. Try a smaller position and observe how it changes your portfolio swings.',q:'A portfolio falls from ₹1,00,000 to ₹80,000. What gain restores it?',opts:['20%','25%','80%'],answer:1,why:'₹20,000 divided by the remaining ₹80,000 is 25%. Losses and recovery gains are not symmetric.'},{title:'Good experiments beat good stories.',tag:'STRATEGY & REFLECTION',text:'A backtest asks what a written rule would have done on historical data. It does not prove future success. Look-ahead bias occurs when your rule uses information unavailable at the time of a trade. Overfitting happens when you tune a rule to past noise. Use the same dates, capital and costs for comparisons; check other periods and stocks. Record your thesis before buying, and review whether the evidence changed before selling.',q:'Which backtest is more credible?',opts:['One that uses tomorrow’s price for today’s decision','One tuned until past performance is perfect','One that uses known information and executes on the next session'],answer:2,why:'Information must exist before the order. Out-of-sample testing and transaction costs make the experiment more useful.'}];
function learnView(){return`<div class="callout"><strong>${state.completed.length} / 6 lessons completed.</strong> Read one idea, answer one question, then test it on the trading floor. Your progress stays in this browser and is included in your backup.</div><div class="lesson-grid">${lessons.map((l,i)=>`<section class="panel lesson"><span class="number">${String(i+1).padStart(2,'0')} ${state.completed.includes(i)?'<span class="pill">COMPLETED ✓</span>':''}</span><span class="eyebrow">${l.tag}</span><h3 style="margin-top:10px">${l.title}</h3><p>${l.text.slice(0,125)}…</p><button class="btn" data-lesson="${i}">Read the lesson ↗</button></section>`).join('')}</div><section class="panel"><div class="insight"><span class="eyebrow">YOUR FIRST INVESTING ROUTINE</span><h3>Think. Allocate. Observe. Reflect.</h3><p>Describe a company's business in two sentences. Write the main risk. Choose a small position size. Pair it with a different source of business exposure. Record your reason for entry and a condition that would invalidate it. Advance several sessions and review the evidence, not just the profit.</p><p>For real company research, use <a href="https://www.bseindia.com/" target="_blank" rel="noopener">BSE filings</a> and the company's investor-relations reports. Continue learning at <a href="https://investor.sebi.gov.in/" target="_blank" rel="noopener">SEBI Investor</a> and <a href="https://www.nism.ac.in/" target="_blank" rel="noopener">NISM</a>.</p></div></section>`}
function settingsView(){return`<div class="settings-grid"><section class="panel"><div class="panel-head"><h2>The data desk</h2><span class="pill">${data.mode.toUpperCase()}</span></div><div class="panel-body"><div class="metric-list"><div><span>Exchange universe</span><strong>BSE / .BO symbols</strong></div><div><span>Sessions per stock</span><strong>${stock().bars.length}</strong></div><div><span>Last available date</span><strong>${date(stock().bars.at(-1).date)}</strong></div><div><span>Dataset ID</span><strong style="font-size:9px">${esc(data.id)}</strong></div></div><p class="fine"><b>Source:</b> ${esc(data.source)}</p><p class="fine"><b>Price basis:</b> ${esc(data.priceBasis)}</p><div class="callout">The included dataset is synthetic unless labelled historical. It uses real BSE company names with fictitious prices. It is never described as live. API refresh replaces it with a new historical replay; portfolios cannot be mixed between datasets.</div><label class="form-label" for="apiEndpoint">HTTPS dataset endpoint (optional)</label><input id="apiEndpoint" type="url" placeholder="https://your-server.example/bse-data.json"><p class="fine">Must return the documented version-1 JSON dataset, allow browser CORS, and contain only 30+ day old BSE data. No API secrets belong in a public website.</p><button class="text-link" id="dataGuide" style="margin-top:14px">How to get free BSE history ↗</button><div style="display:flex;gap:9px;margin-top:15px;flex-wrap:wrap"><button class="btn dark" id="connectApi">Connect endpoint</button><button class="btn" id="reloadData">Load site data.json</button><button class="btn" id="importData">Import data file</button></div><input id="dataFile" type="file" accept="application/json,.json" hidden><p class="fine" id="apiStatus" role="status"></p></div></section><section class="panel"><div class="panel-head"><h2>Your practice, preserved</h2></div><div class="panel-body"><p style="font-size:12px;line-height:1.8">Portfolios and learning progress are saved locally in this browser. There is no account or cloud sync. Export a backup before changing devices or clearing browser data.</p><div style="display:flex;gap:10px;margin:20px 0"><button class="btn dark" id="exportBackup">Export backup ↓</button><button class="btn" id="importBackup">Restore backup ↑</button></div><input id="backupFile" type="file" accept="application/json,.json" hidden><div class="callout">Backups include the exact dataset, portfolio ledger and replay position, so an experiment remains reproducible.</div><label class="form-label" for="renamePortfolio">Active portfolio name</label><input id="renamePortfolio" maxlength="80" value="${esc(active().name)}"><button class="btn" id="saveName" style="margin-top:10px">Save name</button><p class="fine">${esc(active().name)} · ${esc(active().strategy)}</p></div></section></div><section class="panel"><div class="panel-head"><h2>Model assumptions & publishing</h2></div><div class="panel-body"><div class="pair-grid"><div><h3>Execution</h3><p class="fine">Manual orders use the visible replay close, plus simulated slippage and fees. This is deliberately simplified: no bid/ask book, liquidity constraints, intraday fills, tax calculation or real broker settlement.</p></div><div><h3>Corporate actions</h3><p class="fine">The fetch script uses adjusted OHLC prices. These are educational price units, not historical raw exchange quotes. Splits and distributions are reflected in the adjustment; the app does not separately credit dividends.</p></div><div><h3>GitHub Pages ready</h3><p class="fine">This app is static and needs no build. Upload the provided folder to GitHub, turn on Pages, and run the included BSE data-refresh workflow when you want actual historical data.</p></div></div><div class="callout">SEBI's 8 May 2026 circular prescribes a 30-day lag for educational market data from 1 July 2026. This project enforces that lag in its fetch script and dataset validator. Data access and redistribution rights still depend on the source; free/open-source software does not grant market-data rights. <a href="https://www.sebi.gov.in/sebi_data/attachdocs/may-2026/1778242522289.pdf" target="_blank" rel="noopener">Read the circular ↗</a></div></div></section>`}
function quote(){let n=Number($('#quantity')?.value),p=active(),s=stock();try{let x=execution(side,n,last(s).c);$('#tradeSummary').innerHTML=`<div><span>Replay close</span><b>${fmt(last(s).c)}</b></div><div><span>Simulated fill</span><b>${fmt(x.fill)}</b></div><div><span>Fee (0.10%)</span><b>${fmt(x.fee)}</b></div><div><span>${side==='buy'?'Total debit':'Net proceeds'}</span><b>${fmt(x.total)}</b></div>`;$('#reviewOrder').disabled=side==='buy'?x.total>p.cash:n>(p.holdings[s.symbol]?.qty||0);if($('#reviewOrder').disabled)$('#tradeSummary').innerHTML+=`<div class="error">${side==='buy'?'Insufficient available cash.':'Insufficient shares to sell.'}</div>`}catch{$('#tradeSummary').innerHTML='<div class="error">Enter a positive whole number of shares.</div>';$('#reviewOrder').disabled=true}}
function reviewOrder(){let qty=Number($('#quantity').value),note=$('#tradeNote').value,p=active(),s=stock(),orderSide=side,index=state.cursor,x;try{x=execution(side,qty,last(s).c)}catch(e){toast(e.message);return}dialog(`<span class="eyebrow">REVIEW YOUR PAPER ORDER</span><h2>${orderSide==='buy'?'Buy':'Sell'} ${qty} ${esc(s.symbol)}</h2><div class="metric-list"><div><span>Portfolio</span><strong>${esc(p.name)}</strong></div><div><span>Replay session</span><strong>${date(last(s).date)}</strong></div><div><span>Fill / share</span><strong>${fmt(x.fill)}</strong></div><div><span>Fee</span><strong>${fmt(x.fee)}</strong></div><div><span>${side==='buy'?'Total debit':'Net proceeds'}</span><strong>${fmt(x.total)}</strong></div></div><p class="fine">${esc(note||'No thesis recorded. Consider writing one before your next trade.')}</p><div class="callout">${data.mode==='demo'?'Synthetic practice price.':'Adjusted historical practice price.'} This order moves virtual money inside this app only.</div><div class="actions"><button class="btn" id="cancelOrder">Go back</button><button class="btn green" id="confirmOrder">Confirm paper ${side}</button></div>`);$('#cancelOrder').onclick=()=>$('#modal').close();$('#confirmOrder').onclick=()=>{if(state.cursor!==index||p!==active()){toast('Session changed. Review a new order.');$('#modal').close();return}try{trade(p,orderSide,s.symbol,qty,s.bars[index].c,s.bars[index].date,index,note);snapshot(p);save();$('#modal').close();render();toast(`Paper ${orderSide} filled: ${qty} ${s.symbol} at ${fmt(x.fill)}.`)}catch(e){toast(e.message)}}}
function newPortfolio(){if(state.portfolios.length>=20){toast('Maximum 20 portfolios. Export and restart to begin a new experiment.');return}dialog(`<span class="eyebrow">GIVE YOUR IDEA A HOME</span><h2>Create a portfolio</h2><label class="form-label" for="newName">Name</label><input id="newName" maxlength="80" placeholder="e.g. The patient investor"><label class="form-label" for="newStrategy">Investing philosophy</label><select id="newStrategy"><option>Custom</option><option>Buy & hold</option><option>Trend following</option><option>Mean reversion</option><option>Sector diversification</option></select><p class="fine">Starts with ₹1,00,000 virtual cash at the current replay session. A philosophy is a journal label: it does not place automatic trades.</p><div class="actions"><button class="btn dark" id="createPortfolio">Create portfolio →</button></div>`);$('#createPortfolio').onclick=()=>{let name=$('#newName').value.trim();if(!name){$('#newName').focus();toast('Give the portfolio a name.');return}let p=portfolio(name,$('#newStrategy').value);snapshot(p);state.portfolios.push(p);state.active=p.id;save();$('#modal').close();render();toast('Your portfolio is ready.')}}
function advance(n){if($('#modal').open||busy)return;for(let j=0;j<n&&state.cursor<stock().bars.length-1;j++){state.cursor++;for(let p of state.portfolios){applyAuto(p,data.stocks,state.cursor);snapshot(p)}}labResults=null;save();render();if(state.cursor===stock().bars.length-1)toast('End of available history. Restart to try a new experiment.')} 
function restart(){dialog(`<span class="eyebrow">A NEW STARTING LINE</span><h2>Restart this experiment?</h2><p>This clears your portfolios, trades and replay progress for the active dataset. Completed lessons stay with you. Export a backup first if you want to keep this experiment.</p><div class="actions"><button class="btn" id="exportBeforeReset">Export backup ↓</button><button class="btn red" id="confirmReset">Restart portfolios</button></div>`);$('#exportBeforeReset').onclick=exportBackup;$('#confirmReset').onclick=()=>{let completed=state.completed;state=fresh(data);state.completed=completed;labResults=null;save();$('#modal').close();render();toast('A fresh experiment. Same data, new possibilities.')}}
function exportBackup(){const blob=new Blob([JSON.stringify({app:'dalal-street-lab',version:1,data,state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='dalal-street-backup-'+last(stock()).date+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported. Keep it to restore this experiment.')} 
async function readFile(file){if(!file||file.size>8*1024*1024)throw Error('Choose a JSON file smaller than 8 MB.');return JSON.parse(await file.text())}
function changeDataset(d){validateDataset(d);if(d.id===data.id){toast('This dataset is already active.');return}dialog(`<span class="eyebrow">NEW MARKET HISTORY</span><h2>Start with ${d.mode==='demo'?'illustrative':'BSE historical'} data?</h2><p>${d.stocks.length} stocks · ${d.stocks[0].bars.length} sessions · through ${date(d.stocks[0].bars.at(-1).date)}.</p><p class="fine">Source: ${esc(d.source)}</p><p>This replaces the current experiment with empty portfolios. Your existing trades belong to a different price history. Export them first to keep a copy.</p><div class="actions"><button class="btn" id="exportBeforeChange">Export backup ↓</button><button class="btn dark" id="applyDataset">Start new replay →</button></div>`);$('#exportBeforeChange').onclick=exportBackup;$('#applyDataset').onclick=()=>{let completed=state.completed;data=d;state=fresh(d);state.completed=completed;symbol=d.stocks[0].symbol;labResults=null;save();$('#modal').close();render();toast('New history loaded. A new practice session is ready.')}}
async function fetchDataset(url){if(busy)return;busy=true;const status=$('#apiStatus');if(status)status.textContent='Fetching data…';try{let u=new URL(url,location.href);if(u.origin!==location.origin&&u.protocol!=='https:')throw Error('External endpoints must use HTTPS.');let res=await fetch(u,{signal:AbortSignal.timeout(30000),cache:'no-store',credentials:'omit'});if(!res.ok)throw Error(`Data endpoint returned HTTP ${res.status}.`);let text=await res.text();if(text.length>8*1024*1024)throw Error('Dataset is too large. Maximum 8 MB.');let d=validateDataset(JSON.parse(text));if(status)status.textContent='Data validated. Ready to load.';changeDataset(d)}catch(e){if(status)status.textContent='Data unavailable: '+e.message;toast('Could not load data. Your current experiment is unchanged.')}finally{busy=false}}
function showLesson(i){let l=lessons[i];dialog(`<span class="eyebrow">LESSON ${String(i+1).padStart(2,'0')} / ${l.tag}</span><h2>${l.title}</h2><p>${l.text}</p><div class="callout"><b>Check your understanding</b><br>${l.q}</div><div class="quiz-options">${l.opts.map((o,n)=>`<button class="btn" data-answer="${n}">${esc(o)}</button>`).join('')}</div><p id="quizFeedback" role="status" class="fine"></p>`);$('#modalContent').querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{let correct=Number(b.dataset.answer)===l.answer;$('#quizFeedback').textContent=(correct?'Correct. ':'Try again. ')+l.why;$('#quizFeedback').className=correct?'positive-note':'error';if(correct){if(!state.completed.includes(i))state.completed.push(i);save();render();$('#modalContent').querySelectorAll('[data-answer]').forEach(x=>x.disabled=true)}})}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));document.querySelectorAll('[data-range]').forEach(b=>b.onclick=()=>{range=Number(b.dataset.range);render()});document.querySelectorAll('[data-side]').forEach(b=>b.onclick=()=>{side=b.dataset.side;render()});document.querySelectorAll('[data-select-portfolio]').forEach(b=>b.onclick=()=>{state.active=b.dataset.selectPortfolio;save();render()});document.querySelectorAll('[data-open-stock]').forEach(b=>b.onclick=()=>{symbol=b.dataset.openStock;navigate('market')});document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>showLesson(Number(b.dataset.lesson)));
if(page==='market'){const choose=e=>{let row=e.target.closest('[data-stock]');if(row){symbol=row.dataset.stock;render()}};$('#watchRows').onclick=choose;$('#search').oninput=e=>{query=e.target.value;$('#watchRows').innerHTML=watchRows()};$('#tradePortfolio').onchange=e=>{state.active=e.target.value;save();render()};$('#tradeSymbol').onchange=e=>{symbol=e.target.value;render()};$('#quantity').oninput=quote;$('#maxQty').onclick=()=>{let s=stock(),p=active(),n;if(side==='sell')n=p.holdings[s.symbol]?.qty||0;else{let fill=round(last(s).c*(1+COST.slippage));n=Math.floor(p.cash/(fill*(1+COST.fee)));while(n>0&&execution('buy',n,last(s).c).total>p.cash)n--}$('#quantity').value=Math.min(n,10000000);quote()};$('#reviewOrder').onclick=reviewOrder;quote()}
document.querySelectorAll('[data-auto-portfolio]').forEach(b=>b.onclick=()=>autoDialog(b.dataset.autoPortfolio));
if(page==='portfolios'){$('#newPortfolio').onclick=newPortfolio;$('#pairBase').onchange=e=>{symbol=e.target.value;render()}}
if(page==='lab'){$('#runLab').onclick=()=>{let sym=$('#labStock').value,window=Number($('#labWindow').value),s=data.stocks.find(x=>x.symbol===sym),a=bars(s).slice(-window);try{labResults={symbol:sym,window,start:a[50].date,end:a.at(-1).date,items:[['hold','Buy & hold'],['trend','Trend following'],['rsi','Mean reversion']].map(([rule,name])=>({...backtest(a,rule),name}))};render()}catch(e){toast(e.message)}}}
if(page==='settings'){$('#dataGuide').onclick=()=>dialog(`<span class="eyebrow">FROM PRACTICE DATA TO BSE HISTORY</span><h2>Bring the exchange into your replay.</h2><p>The download includes a free, open-source yfinance fetch script. It retrieves actual BSE historical OHLCV in INR and keeps a 31-day lag.</p><p>Follow the README's data setup instructions to generate <b>bse-history.json</b> on your computer, or run the included fetch workflow in a private GitHub repository. Then use <b>Import data file</b> on this screen.</p><div class="callout">The provider can rate-limit or deny requests. The script validates currency, exchange and common dates, and never writes fabricated replacements. Downloaded data is subject to the provider's personal-use terms; public redistribution requires appropriate rights.</div><p class="fine">For a different authorized provider, configure an HTTPS endpoint that returns the documented version-1 dataset. API keys stay on your server.</p>`);$('#exportBackup').onclick=exportBackup;$('#importBackup').onclick=()=>$('#backupFile').click();$('#backupFile').onchange=async e=>{try{let b=await readFile(e.target.files[0]);if(b.app!=='dalal-street-lab'||b.version!==1)throw Error('Not a Dalal Street Lab backup.');let d=validateDataset(b.data),s=validateState(b.state,d);dialog(`<h2>Restore this experiment?</h2><p>${s.portfolios.length} portfolios, at ${date(d.stocks[0].bars[s.cursor].date)}. This replaces your current browser experiment.</p><div class="actions"><button class="btn" id="exportBeforeRestore">Export current backup</button><button class="btn dark" id="confirmRestore">Restore</button></div>`);$('#exportBeforeRestore').onclick=exportBackup;$('#confirmRestore').onclick=()=>{data=d;state=s;symbol=d.stocks[0].symbol;labResults=null;save();$('#modal').close();render();toast('Your experiment was restored.')}}catch(e){toast('Import rejected: '+e.message)}};$('#saveName').onclick=()=>{let name=$('#renamePortfolio').value.trim();if(!name){toast('Enter a portfolio name.');return}active().name=name;save();render();toast('Portfolio renamed.')};$('#connectApi').onclick=()=>{let u=$('#apiEndpoint').value.trim();if(!u){toast('Enter an HTTPS dataset endpoint.');return}fetchDataset(u)};$('#reloadData').onclick=()=>fetchDataset('./data.json');$('#importData').onclick=()=>$('#dataFile').click();$('#dataFile').onchange=async e=>{try{changeDataset(await readFile(e.target.files[0]))}catch(e){toast('Data import rejected: '+e.message)}}}}
function navigate(p){if(!['market','portfolios','lab','learn','settings'].includes(p))p='market';page=p;history.replaceState(null,'','#'+p);render();window.scrollTo({top:0,behavior:'instant'})}
$('#nav').querySelectorAll('button').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$('#nextDay').onclick=()=>advance(1);$('#nextWeek').onclick=()=>advance(5);$('#restart').onclick=restart;$('#exportTop').onclick=exportBackup;window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));window.addEventListener('storage',e=>{if(e.key===KEY){stale=true;toast('Another tab changed this experiment. Reload this tab to continue safely.')}});document.addEventListener('click',e=>{if(stale){e.preventDefault();e.stopImmediatePropagation();toast('Another tab changed this experiment. Reload this tab to continue safely.')}},true);
async function init(){try{let shipped=validateDataset(await(await fetch('./data.json')).json()),stored;try{stored=JSON.parse(localStorage.getItem(KEY)||'null')}catch{}if(stored){try{data=validateDataset(stored.data);state=validateState(stored.state,data)}catch{data=shipped;state=fresh(data);toast('Saved state was invalid. Started a fresh practice session.')}}else{data=shipped;state=fresh(data)}symbol=data.stocks[0].symbol;page=location.hash.slice(1)||'market';if(!['market','portfolios','lab','learn','settings'].includes(page))page='market';save();render();if(shipped.id!==data.id)toast('Updated site data is available. Open Data & settings to load it.')}catch(e){$('#view').innerHTML=`<section class="panel"><div class="panel-body"><h2>The practice floor could not load.</h2><p>${esc(e.message)}</p><p class="fine">Serve this folder over HTTP (GitHub Pages or python3 -m http.server 8000). Opening index.html directly as a file does not support module imports and data loading.</p><button class="btn" onclick="location.reload()">Retry</button></div></section>`;$('#nextDay').disabled=$('#nextWeek').disabled=$('#restart').disabled=$('#exportTop').disabled=true}}
init();

function autoDialog(id){let p=state.portfolios.find(x=>x.id===id);dialog(`<span class="eyebrow">A RULE, NOT A PREDICTION</span><h2>Automate your replay</h2><p class="fine">${esc(p.name)} · runs only when you advance sessions. Signals use the prior close; orders fill at the next open with the same fees and slippage. This does not run in the background or send real orders.</p><label class="form-label" for="autoStock">Stock</label><select id="autoStock">${data.stocks.map(s=>`<option value="${esc(s.symbol)}" ${s.symbol===(p.auto?.symbol||symbol)?'selected':''}>${esc(s.symbol)}</option>`).join('')}</select><label class="form-label" for="autoRule">Rule</label><select id="autoRule"><option value="hold">Buy & hold: one entry, no automatic exit</option><option value="trend">Trend: hold when SMA 20 &gt; SMA 50</option><option value="rsi">Mean reversion: buy RSI &lt; 30, sell RSI &gt; 70</option></select><label class="form-label" for="autoAllocation">Entry size (% of portfolio equity)</label><input id="autoAllocation" type="number" min="5" max="100" step="1" value="${p.auto?p.auto.allocation*100:25}"><div class="callout">One open position per rule. No pyramiding or leverage. The rule can sell all holdings of its selected stock, including shares you purchased manually. Other holdings are left alone. Costs, gaps and false signals can produce losses.</div><div class="actions"><button class="btn" id="disableAuto">Turn off</button><button class="btn dark" id="enableAuto">Enable replay rule</button></div>`);if(p.auto)$('#autoRule').value=p.auto.rule;$('#disableAuto').onclick=()=>{p.auto=null;save();$('#modal').close();render();toast('Automatic rule disabled.')};$('#enableAuto').onclick=()=>{let allocation=Number($('#autoAllocation').value)/100;if(!Number.isFinite(allocation)||allocation<.05||allocation>1){toast('Entry size must be between 5% and 100%.');return}p.auto={rule:$('#autoRule').value,symbol:$('#autoStock').value,allocation};save();$('#modal').close();render();toast('Rule enabled. Advance a session to evaluate the prior close.')}}
